import{_ as t,o,c as a,ag as e}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"科学日报 · 2026-09-13（AI 前沿）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-09-13.md","filePath":"topics/ai-system-architecture/science-daily-2026-09-13.md"}'),r={name:"topics/ai-system-architecture/science-daily-2026-09-13.md"};function l(n,i,s,u,c,h){return o(),a("div",null,[...i[0]||(i[0]=[e('<h1 id="科学日报-·-2026-09-13-ai-前沿" tabindex="-1">科学日报 · 2026-09-13（AI 前沿） <a class="header-anchor" href="#科学日报-·-2026-09-13-ai-前沿" aria-label="Permalink to &quot;科学日报 · 2026-09-13（AI 前沿）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-13.md</code> — 第24期</p></blockquote><hr><h2 id="边缘可部署-vlm-真能识别物种吗-arxiv-2609-11916" tabindex="-1">边缘可部署 VLM 真能识别物种吗？（arXiv:2609.11916） <a class="header-anchor" href="#边缘可部署-vlm-真能识别物种吗-arxiv-2609-11916" aria-label="Permalink to &quot;边缘可部署 VLM 真能识别物种吗？（arXiv:2609.11916）&quot;">​</a></h2><ul><li>相机陷阱多在边缘硬件/弱联网下运行，故 2–8B 的小型本地 VLM 才是物种识别最相关的评测对象（而非前沿大模型）。</li><li>96 物种任务上横向对比 4 个 VLM（Qwen3-VL 2B/4B/8B、Gemma3 4B）与专用小模型 BioCLIP（300M），用干净 iNaturalist 照片 + 6 个 LILA 实测集双评估集交叉验证。</li><li>结论：所有模型远高于随机，但在野外图像上普遍大幅退化（域差 9.6–26.6pp，跨分类层级一致），且退化更多源于<strong>图像可读性</strong>而非细粒度判别失效；BioCLIP 以更小参数量全面碾压（+33.2–59.2pp），指向<strong>专用训练数据而非模型规模</strong>才是关键。开放提示下 5.9–9.6% 回应是语法合法但分类学不存在的物种名（虚构率排名跨评估集可复现）。</li><li>洞察：与&quot;边缘部署≠能力充足&quot;的母题同向——<strong>部署约束决定什么路线的模型才值得评测</strong>；且&quot;虚构率可复现排序&quot;提示幻觉也可作为稳定的相对基准。</li></ul><h2 id="纤维化最优传输的模型感知生成调度-arxiv-2609-11842" tabindex="-1">纤维化最优传输的模型感知生成调度（arXiv:2609.11842） <a class="header-anchor" href="#纤维化最优传输的模型感知生成调度-arxiv-2609-11842" aria-label="Permalink to &quot;纤维化最优传输的模型感知生成调度（arXiv:2609.11842）&quot;">​</a></h2><ul><li>扩散/流匹配的噪声调度控制信号-噪声混合，但既有动能调度是<strong>模型无关</strong>的、忽略预测误差。</li><li>提出基于<strong>纤维化最优传输</strong>（fiberwise OT）的模型感知调度：在概率路径固定时间-状态上，兼容分解构成&quot;仿射纤维&quot;，对纤维内真值与预测诱导分解的 OT 代价取平均定义&quot;纤维化预测风险&quot;，与路径动能组合得闭式最优时间分配，并可从早期检查点估计风险谱。</li><li>CIFAR-10 流匹配 16 次函数评估下相对 FID 降 38.6%；标准化风险谱与调度形变跨设定高度对齐（经验普适性），冻结的解析模板即可保留大部分收益。</li><li>洞察：把&quot;模型主观误差&quot;纳进调度设计，是生成工程里&quot;损失/成本与模型实际能力对齐&quot;的又一例证——与 [fiberwise 相关调度优化] 的一贯主题一致。</li></ul><h2 id="thinking-with-looped-flows-用更多计算换更难问题-arxiv-2609-11801" tabindex="-1">Thinking with Looped Flows：用更多计算换更难问题（arXiv:2609.11801） <a class="header-anchor" href="#thinking-with-looped-flows-用更多计算换更难问题-arxiv-2609-11801" aria-label="Permalink to &quot;Thinking with Looped Flows：用更多计算换更难问题（arXiv:2609.11801）&quot;">​</a></h2><ul><li>循环模型在推理时重复更新隐状态以&quot;用时间换计算&quot;，但其训练往往只对少数更新反传，难以让早期更新服务后续更新。</li><li>looped flows：用<strong>局部去噪目标</strong>训练循环，通过逐步降低噪声级 + 共享噪声对不同去噪目标施加时间关联，逼出可随时间迁移有用计算的循环状态；推理 = 对学习去噪器参数化的概率流速度积分，用更细时间网格换更大计算。</li><li>ARC-AGI-1 58.8%、ARC-AGI-2 12.2%，整体优于现有循环模型 SOTA（含两个多解基准）；可从不同初始噪声给出多个有效预测。</li><li>洞察：与 [echo-gap 记忆-奖励] 的&quot;推理即时间&quot;同向——<strong>把推理成本显式映射到时间网格</strong>，是测试时计算扩展（TTC）路线的一个优雅实现。</li></ul><h2 id="logit-refiner-尺度内依赖修复视觉自回归模型-arxiv-2609-11804" tabindex="-1">Logit Refiner：尺度内依赖修复视觉自回归模型（arXiv:2609.11804） <a class="header-anchor" href="#logit-refiner-尺度内依赖修复视觉自回归模型-arxiv-2609-11804" aria-label="Permalink to &quot;Logit Refiner：尺度内依赖修复视觉自回归模型（arXiv:2609.11804）&quot;">​</a></h2><ul><li>视觉自回归模型（VAR）同尺度内 token 并行解码，作者论证这是<strong>平均场式近似</strong>，丢弃尺度内空间依赖，导致局部不连贯采样——解码规则本身的局限，而非骨干容量问题。</li><li>Logit Refiner：超轻量自回归模块，基于冻结骨干特征序列化采样 token 以恢复尺度内依赖；仅 +~10% 参数、&lt;5% 基座训练算力，即插即用于任意预训练 VAR 检查点、无需重训。</li><li>受控消融证明关键成分是&quot;尺度内联合采样&quot;；ImageNet 256×256 上 310M–2B 骨干一致提升，1.1B 超越两倍体量模型，并泛化到文生图。</li><li>洞察：&quot;并行解码的瓶颈可建模为缺失的依赖结构&quot;——与 [vibe-coding]/[llm-reasoning-verification] 中&quot;显式建模被近似丢弃的结构&quot;的母题同构。</li></ul><h2 id="生成式营销组合建模-gmmm-把-geo-gem-纳入因果归因-arxiv-2609-11915" tabindex="-1">生成式营销组合建模 GMMM：把 GEO/GEM 纳入因果归因（arXiv:2609.11915） <a class="header-anchor" href="#生成式营销组合建模-gmmm-把-geo-gem-纳入因果归因-arxiv-2609-11915" aria-label="Permalink to &quot;生成式营销组合建模 GMMM：把 GEO/GEM 纳入因果归因（arXiv:2609.11915）&quot;">​</a></h2><ul><li>生成式 AI 改变触达方式，但标准营销数据不记录&quot;用户在生成答案里看到并注意到企业名&quot;——GEO/GEM 的归因存在数据缺口。</li><li>GMMM：GEO 侧组合重复生成答案 + 问题数 + 各生成系统占比 + 注意概率；GEM 侧组合广告位记录 + 注意概率；在备选处理序列下比较期望业务响应，并给出效应<strong>可识别性充分条件</strong>。</li><li>以英日双语产品推荐模拟答案验证表现。</li><li>洞察：把&quot;生成引擎&quot;作为新的触达渠道纳入因果营销建模——对广告预算在 AI 答案生态的分配有直接参考意义；与因果推断主题一贯的关注点（识别条件 &gt; 预测精度）一致。</li></ul>',13)])])}const q=t(r,[["render",l]]);export{g as __pageData,q as default};
